// ── Parse & validate incoming request ───────────────────────────
const body = $json.body;
if (!body || typeof body !== 'object') throw new Error('400: Missing request body');

const origin      = (body.origin      || '').trim();
const airportName = (body.airportName || '').trim();
const iata        = (body.iata        || '').trim().toUpperCase();
const terminal    = (body.terminal    || '').trim();
const flightDate  = (body.flightDate  || '').trim();
const flightTime  = (body.flightTime  || '').trim();
const flightType  = (body.flightType  || 'international').trim();
const traveller   = (body.traveller   || '').trim();
const extras      = (body.extras      || '').trim();

if (!origin)      throw new Error('400: origin is required');
if (!airportName) throw new Error('400: airportName is required');
if (!flightDate)  throw new Error('400: flightDate is required');
if (!flightTime)  throw new Error('400: flightTime is required');

// Destination for Google Maps — full airport name works well
const destination = airportName + (terminal ? `, ${terminal}` : '');

// Build departure time ISO string for traffic-aware routing
// Combine flightDate + flightTime, subtract 3h to get a "now" reference time for when they would leave
let departureDatetime = '';
try {
  const flightDt = new Date(`${flightDate}T${flightTime}:00`);
  // We want traffic at departure time, not flight time — subtract 3h as a reasonable estimate
  const trafficCheckTime = new Date(flightDt.getTime() - 3 * 60 * 60 * 1000);
  departureDatetime = trafficCheckTime.toISOString();
} catch(e) {
  departureDatetime = new Date().toISOString();
}

return [{ json: { origin, destination, airportName, iata, terminal, flightDate, flightTime, flightType, traveller, extras, departureDatetime } }];

// ── Combine traffic + delay data ────────────────────────────────
const parsed       = $node['Parse Request'].json;
const routeData    = $node['Google Routes API'].json;
const flightData   = $node['AviationStack Delays'].json;

// ── Drive time ────────────────────────────────────────────────────
let driveMinutes   = null;
let driveMinStatic = null;
let driveText      = 'N/A';
let trafficLevel   = 'amber';
let trafficDelayMin = 0;

try {
  const route = (routeData.routes || [])[0];
  if (route) {
    // duration with traffic (seconds)
    const withTraffic  = parseInt(route.duration)     || 0;
    const withoutTraffic = parseInt(route.staticDuration) || 0;
    driveMinutes   = Math.ceil(withTraffic / 60);
    driveMinStatic = Math.ceil(withoutTraffic / 60);
    trafficDelayMin = Math.max(0, driveMinutes - driveMinStatic);
    driveText = driveMinutes >= 60
      ? `${Math.floor(driveMinutes/60)}h ${driveMinutes%60}m`
      : `${driveMinutes} min`;
    // Traffic level
    const ratio = withoutTraffic > 0 ? withTraffic / withoutTraffic : 1;
    trafficLevel = ratio < 1.15 ? 'green' : ratio < 1.4 ? 'amber' : 'red';
  }
} catch(e) {
  console.error('Route parse error:', e.message);
}

// ── Airport delay data ────────────────────────────────────────────
let delayLevel = 'green';
let delayPct   = 0;
let delayNote  = '';

try {
  const flights = (flightData.data || []);
  if (flights.length > 0) {
    const delayed = flights.filter(f => {
      const dep = f.departure || {};
      return dep.delay && parseInt(dep.delay) > 15;
    });
    delayPct = Math.round((delayed.length / flights.length) * 100);
    delayLevel = delayPct < 20 ? 'green' : delayPct < 45 ? 'amber' : 'red';
    if (delayed.length > 0) {
      const avgDelay = Math.round(delayed.reduce((s, f) => s + parseInt(f.departure?.delay || 0), 0) / delayed.length);
      delayNote = `${delayed.length} of ${flights.length} active flights delayed. Average delay: ${avgDelay} min.`;
    } else {
      delayNote = `${flights.length} active flights checked — most are running on time.`;
    }
  } else {
    delayNote = 'No live flight data available for this airport right now.';
    delayLevel = 'amber';
  }
} catch(e) {
  delayNote = 'Delay data unavailable.';
  delayLevel = 'amber';
}

// ── Calculate "leave by" time ─────────────────────────────────────
let leaveByTime = '';
let leaveBySummary = '';

try {
  const isIntl   = parsed.flightType === 'international';
  const hasKids  = (parsed.traveller || '').includes('family') || (parsed.traveller || '').includes('children');
  const hasCheck = (parsed.traveller || '').includes('checked');

  // Base airport buffer (minutes before flight)
  let airportBuffer = isIntl ? 180 : 120;
  if (hasKids)  airportBuffer += 30;
  if (hasCheck) airportBuffer += 20;
  // Add extra if airport is busy
  if (delayLevel === 'amber') airportBuffer += 15;
  if (delayLevel === 'red')   airportBuffer += 30;
  // Add actual drive time + 10min buffer for parking/drop-off
  const totalMinBefore = airportBuffer + (driveMinutes || 60) + 10;

  const [h, m]   = (parsed.flightTime || '00:00').split(':').map(Number);
  const flightMs = new Date(`${parsed.flightDate}T${String(h).padStart(2,'0')}:${String(m).padStart(2,'0')}:00`).getTime();
  const leaveMs  = flightMs - totalMinBefore * 60 * 1000;
  const leaveDate = new Date(leaveMs);
  leaveByTime = leaveDate.toLocaleTimeString('en-US', { hour: '2-digit', minute: '2-digit', hour12: true });

  const icon = trafficLevel === 'red' || delayLevel === 'red' ? '🔴' : trafficLevel === 'amber' || delayLevel === 'amber' ? '🟡' : '🟢';
  leaveBySummary = `${icon} Leave by ${leaveByTime} — ${driveText || 'drive'} to airport + ${airportBuffer} min check-in buffer${trafficDelayMin > 10 ? ` (includes ${trafficDelayMin} min traffic delay)` : ''}.`;
} catch(e) {
  leaveBySummary = 'Could not calculate leave time — check your flight time input.';
}

return [{ json: {
  ...parsed,
  driveMinutes, driveMinStatic, driveText, trafficLevel, trafficDelayMin,
  delayLevel, delayPct, delayNote, leaveByTime, leaveBySummary
}}];

