// ── Format final response ────────────────────────────────────────
const data  = $node['Combine Traffic + Delays'].json;
const raw   = $node['Claude Departure Guide'].json?.content?.[0]?.text
           || $node['Claude Departure Guide'].json?.message?.content
           || '';

if (!raw) throw new Error('Claude returned empty response');

// Light HTML formatting
const html = raw.trim()
  .replace(/\*\*(.*?)\*\*/g, '<strong>$1</strong>')
  .replace(/\n\n/g, '<br><br>')
  .replace(/\n- /g, '<br>• ')
  .replace(/\n/g, '<br>');

return [{ json: {
  result:        raw.trim(),
  resultHtml:    html,
  // Structured data for the live widget
  driveMinutes:  data.driveMinutes,
  driveMinStatic:data.driveMinStatic,
  driveText:     data.driveText,
  trafficLevel:  data.trafficLevel,
  delayLevel:    data.delayLevel,
  delayPct:      data.delayPct,
  delayNote:     data.delayNote,
  leaveByTime:   data.leaveByTime,
  leaveBySummary:data.leaveBySummary,
  airportName:   data.airportName,
  iata:          data.iata,
}}];
